public class Scope_getReferences_TriageGen1Test {

    @Mock
    private Scope mockScope;

    @Mock
    private Var mockVar;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
    }

    @Test
    public void testGetReferences_returnsSingleElementList() {
        // Given: The method is implemented to return an ImmutableList containing the input var.
        // Since the method is an @Override and we are testing the logic provided:
        // return ImmutableList.of(var);

        // When
        Iterable<Var> result = mockScope.getReferences(mockVar);

        // Then
        assertNotNull("The returned iterable should not be null", result);

        int count = 0;
        for (Var v : result) {
            assertEquals("The element in the list should be the same instance as the input var", mockVar, v);
            count++;
        }
        assertEquals("The list should contain exactly one element", 1, count);
    }

    @Test
    public void testGetReferences_withNullParameter() {
        // Note: The provided implementation ImmutableList.of(var) throws NullPointerException if var is null.
        // This test ensures we capture that behavior (common in Guava-based code).

        try {
            mockScope.getReferences(null);
        } catch (NullPointerException e) {
            // Expected behavior for ImmutableList.of(null)
        }
    }

    @Test
    public void testGetReferences_isImmutable() {
        // Given
        Iterable<Var> result = mockScope.getReferences(mockVar);

        // Since the implementation uses ImmutableList.of, we verify it behaves like a single-element list
        // even if we iterate multiple times.
        Iterable<Var> result2 = mockScope.getReferences(mockVar);

        int count1 = 0;
        for (Var v : result) {
            count1++;
        }

        int count2 = 0;
        for (Var v : result2) {
            count2++;
        }

        assertEquals(1, count1);
        assertEquals(1, count2);
    }
}
